<?php
require_once __DIR__.'/includes/panel_helpers.php';$rolId=exigirRol([1,2,4]);require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../src/Services/pdf_comprobante.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Pago no encontrado.');}
try{$pdo=conectarBD();$s=$pdo->prepare("SELECT pg.*,c.codigo_cita,c.inicio,p.nombres||' '||p.apellidos paciente,p.documento_identidad,p.usuario_id paciente_usuario,e.nombre especialidad,u.nombre registrado_por_nombre FROM pagos pg JOIN citas c ON c.id=pg.cita_id JOIN pacientes p ON p.id=pg.paciente_id JOIN especialidades e ON e.id=c.especialidad_id JOIN usuarios u ON u.id=pg.registrado_por WHERE pg.id=:id");$s->execute(['id'=>$id]);$pago=$s->fetch();if(!$pago){http_response_code(404);exit('Pago no encontrado.');}if($rolId===4&&(int)$pago['paciente_usuario']!==(int)$_SESSION['usuario_id']){http_response_code(403);exit('No tienes permiso para ver este recibo.');}$pdf=generarReciboPagoPdf($pago);$nombre='recibo-'.preg_replace('/[^A-Za-z0-9_-]/','-',$pago['codigo_pago']).'.pdf';header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.$nombre.'"');header('Content-Length: '.strlen($pdf));header('X-Content-Type-Options: nosniff');echo $pdf;}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);exit('No se pudo generar el recibo.');}
